function streamWorld(x,z,force=false){const cx=Math.floor(x/32),cz=Math.floor(z/32);if(!force&&world.cx===cx&&world.cz===cz)return;world.cx=cx;world.cz=cz;const required=new Set();for(let dx=-1;dx<=1;dx++)for(let dz=-1;dz<=1;dz++)required.add((cx+dx)+','+(cz+dz));for(const [key,chunk] of world.chunks){if(required.has(key))continue;scene.remove(chunk.mesh);chunk.mesh.traverse(m=>{if(m.isMesh)m.geometry.dispose();});world.chunks.delete(key);for(let i=obstacles.length-1;i>=0;i--)if(obstacles[i].key===key)obstacles.splice(i,1);if(typeof events!=='undefined')for(let i=events.length-1;i>=0;i--)if(events[i].chunk===key){disposeEvent(events[i]);events.splice(i,1);}}for(const key of required){if(world.chunks.has(key))continue;const [xx,zz]=key.split(',').map(Number);createChunk(xx,zz);}world.dirty=true;}
const nav={w:64,h:64,minX:-32,minZ:-32,walk:new Uint8Array(4096),dist:new Int16Array(4096),queue:new Int16Array(4096),next:0};
function navIndex(x,z){return clamp(Math.floor(z-nav.minZ),0,nav.h-1)*nav.w+clamp(Math.floor(x-nav.minX),0,nav.w-1);}
function updateNavigation(){if(game.time<nav.next&&!world.dirty)return;nav.next=game.time+.7;const nx=Math.floor(game.player.x)-32,nz=Math.floor(game.player.z)-32;if(world.dirty||Math.abs(nx-nav.minX)>3||Math.abs(nz-nav.minZ)>3){nav.minX=nx;nav.minZ=nz;for(let z=0;z<64;z++)for(let x=0;x<64;x++)nav.walk[z*64+x]=isBlocked(x+nx+.5,z+nz+.5,.45)?0:1;world.dirty=false;}nav.dist.fill(-1);let start=navIndex(game.player.x,game.player.z);if(!nav.walk[start]){const sx=start%64,sz=start>>6;let best=1e9;for(let dz=-3;dz<=3;dz++)for(let dx=-3;dx<=3;dx++){const x=sx+dx,z=sz+dz;if(x<0||z<0||x>=64||z>=64)continue;const j=z*64+x;if(nav.walk[j]&&dx*dx+dz*dz<best){best=dx*dx+dz*dz;start=j;}}}let head=0,tail=0;nav.queue[tail++]=start;nav.dist[start]=0;while(head<tail){const i=nav.queue[head++],x=i%64,z=i>>6;for(let dz=-1;dz<=1;dz++)for(let dx=-1;dx<=1;dx++){if(!dx&&!dz)continue;const xx=x+dx,zz=z+dz;if(xx<0||zz<0||xx>=64||zz>=64)continue;const j=zz*64+xx;if(!nav.walk[j]||nav.dist[j]>=0||dx&&dz&&(!nav.walk[z*64+xx]||!nav.walk[zz*64+x]))continue;nav.dist[j]=nav.dist[i]+1;nav.queue[tail++]=j;}}}
function clearRoute(a,b){for(const o of obstacles){let near=0,far=1;for(const [v,d,min,max] of [[a.x,b.x-a.x,o.x-o.w-.45,o.x+o.w+.45],[a.z,b.z-a.z,o.z-o.d-.45,o.z+o.d+.45]]){if(Math.abs(d)<1e-6){if(v<min||v>max){near=2;break;}}else{let p=(min-v)/d,q=(max-v)/d;if(p>q)[p,q]=[q,p];near=Math.max(near,p);far=Math.min(far,q);if(near>far)break;}}if(near<=far&&far>=0&&near<=1)return false;}return true;}
function chaseDirection(e){const p=game.player;if(clearRoute(e,p))return{x:p.x-e.x,z:p.z-e.z};const i=navIndex(e.x,e.z),x=i%64,z=i>>6;let best=1e9,target=null;for(let dz=-1;dz<=1;dz++)for(let dx=-1;dx<=1;dx++){if(!dx&&!dz)continue;const xx=x+dx,zz=z+dz;if(xx<0||zz<0||xx>=64||zz>=64)continue;const j=zz*64+xx;if(!nav.walk[j]||nav.dist[j]<0||dx&&dz&&(!nav.walk[z*64+xx]||!nav.walk[zz*64+x]))continue;const px=xx+nav.minX+.5,pz=zz+nav.minZ+.5,score=nav.dist[j]+Math.hypot(px-e.x,pz-e.z)*.15;if(score<best){best=score;target={x:px-e.x,z:pz-e.z};}}return target||{x:p.x-e.x,z:p.z-e.z};}
