function robeGeometry(rings,segments=24){const p=[],uv=[],idx=[];for(let j=0;j<rings.length;j++){const [y,r]=rings[j];for(let i=0;i<=segments;i++){const a=i/segments*TAU,pleat=1+Math.cos(a*8)*.035;p.push(Math.sin(a)*r*pleat,y,Math.cos(a)*r*.8*pleat);uv.push(i/segments,j/(rings.length-1));}}for(let j=0;j<rings.length-1;j++)for(let i=0;i<segments;i++){const a=j*(segments+1)+i,b=a+segments+1;idx.push(a,b,a+1,b,b+1,a+1);}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(idx);g.computeVertexNormals();return g;}
