const slashVertex='varying vec2 vUv;void main(){vUv=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}';
const slashFragment='varying vec2 vUv;uniform vec3 uColor;uniform float uAlpha;void main(){float edge=pow(max(sin(vUv.y*3.1415926),0.0),.6);float tip=pow(max(sin(vUv.x*3.1415926),0.0),.5);gl_FragColor=vec4(uColor,edge*tip*uAlpha);}';
function slash(x,z,angle,r,color,duration=.3,span=2.5,height=.65){if(effects.length>140)return;const p=[],uv=[],index=[];for(let i=0;i<=32;i++){const a=-span/2+i/32*span;for(let j=0;j<2;j++){const radius=r-(j?Math.max(.2,r*.10):0);p.push(Math.sin(a)*radius,Math.sin(i/32*Math.PI)*.14,Math.cos(a)*radius);uv.push(i/32,j);}}for(let i=0;i<32;i++){const a=i*2;index.push(a,a+1,a+2,a+1,a+3,a+2);}const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(p,3));g.setAttribute('uv',new T.Float32BufferAttribute(uv,2));g.setIndex(index);const mat=new T.ShaderMaterial({uniforms:{uColor:{value:new T.Color(color)},uAlpha:{value:.72}},vertexShader:slashVertex,fragmentShader:slashFragment,transparent:true,depthWrite:false,side:T.DoubleSide,blending:T.AdditiveBlending});const mesh=new T.Mesh(g,mat);mesh.position.set(x,height,z);mesh.rotation.y=angle;scene.add(mesh);effects.push({mesh,t:0,d:duration,r:1,kind:'slash',angle,ownGeo:true});}
