addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code)&&state!=='home')e.preventDefault();if(e.repeat)return;if(e.code==='Escape'){if(state==='playing'&&!qaRunning)pauseGame();else if(state==='paused'||state==='book')closeModal();else if(state==='guide')$('guide-close').click();return;}if(e.code==='KeyB'&&game){if(state==='book')closeModal();else if(state==='playing'||state==='paused')openBook();return;}if(state==='upgrade'&&['Digit1','Digit2','Digit3'].includes(e.code)){const id=game.choices[+e.code.slice(-1)-1];if(id)selectUpgrade(id);return;}if(state!=='playing')return;keys.add(e.code);if(e.code==='Space')doDash();if(e.code==='KeyQ')ultimate();if(e.code==='KeyE')signature();});
addEventListener('keyup',e=>keys.delete(e.code));addEventListener('blur',()=>{keys.clear();stick.x=stick.z=0;pointer.held=false;if(state==='playing')pauseGame();});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing'&&!qaRunning)pauseGame();});
